def consume(ref: Ref[IO, Set[String]], msg: Message): IO[Unit] =
  ref.modify(seen => (seen + msg.key, seen.contains(msg.key))).flatMap { duplicate =>
    if (duplicate) ack(msg)                // duplicate: absorb
    else applyEffects(msg) >> ack(msg)
  }
